#!/usr/bin/env ruby
require 'json';require 'fileutils'
root=File.expand_path('..',__dir__);client=File.expand_path('../Client',root);temp=File.join(client,'temp');files=Dir.glob(File.join(temp,'**/*'),File::FNM_DOTMATCH).select{|p|File.file?(p)};tool=File.read(File.join(root,'tools/clean-client-generated.sh'));ignore=File.read(File.join(client,'.gitignore'));checks={tempIgnored:ignore.lines.map(&:strip).include?('/temp/'),dryRunDefault:tool.include?('mode=${1:---dry-run}'),explicitApply:tool.include?('--apply'),creatorProcessGuard:tool.include?('pgrep'),pathAllowlist:tool.include?('unsafe path'),sourceTsconfigRegenerationDependency:File.read(File.join(client,'tsconfig.json')).include?('./temp/tsconfig.cocos.json')};report={schemaVersion:1,tempFiles:files.length,bytes:files.sum{|p|File.size(p)},checks:checks,passed:checks.values.all?};out=File.join(root,'docs/generated/chyg03-temp-cleanup.json');FileUtils.mkdir_p(File.dirname(out));File.write(out,JSON.pretty_generate(report)+"\n");abort "CHYG03 failed: #{checks}" unless report[:passed];puts 'CHYG03 PASS: temp is generated-only and cleanup is guarded, dry-run by default'
